 @SuppressWarnings({"rawtypes","unchecked"})static void copyProgress(Object p,Object v)throws IOException{try{for(Field f:p.getClass().getDeclaredFields())if(!Modifier.isStatic(f.getModifiers())){f.setAccessible(true);Object x=copy(f.get(p)),old=f.get(v);if(old instanceof Map){((Map)old).clear();((Map)old).putAll((Map)x);}else if(old instanceof Set){((Set)old).clear();((Set)old).addAll((Set)x);}else{if(Modifier.isFinal(f.getModifiers()))throw new IOException("Progress final scalar");f.set(v,x);}}}catch(IllegalAccessException e){throw new IOException(e);}}
 static Object copy(Object v)throws IOException{if(v instanceof byte[])return((byte[])v).clone();if(v instanceof Map){Map<Object,Object>m=new LinkedHashMap<>();for(Map.Entry<?,?>e:((Map<?,?>)v).entrySet())m.put(e.getKey(),copy(e.getValue()));return m;}if(v instanceof Set){Set<Object>s=new LinkedHashSet<>();for(Object x:(Set<?>)v)s.add(copy(x));return s;}if(v==null||v instanceof String||v instanceof Number||v instanceof Boolean)return v;throw new IOException("Unreviewed dream copy type");}
